<script>
    // Embedded Decks
    const decks = {
        audience: [
            "A high-stakes venture capitalist who hates jargon",
            "A stressed-out college student studying for finals",
            "An AI assistant designed to be clinical and direct",
            "A cynical software engineer looking for architecture flaws"
        ],
        task: [
            "Explain the technical breakdown of Game Theory Optimal poker strategies",
            "Draft a brutal, objective code review focusing on performance bottlenecks",
            "Create a rigorous workout split targeting high protein efficiency",
