    function clearSlot(type) {
        currentSelections[type] = null;
        updateSlotDisplay(type);
        compileRecipe();
    }

    // Update the UI Box for Specific Type
    function updateSlotDisplay(type) {
        const slot = document.getElementById(`slot-${type}`);
        const value = currentSelections[type];

        if (value) {
