            let labelColor = `var(--accent-${type.substring(0,3)})`;
            slot.innerHTML = `
                <span class="slot-label" style="color:${labelColor}">${type} Slot</span>
                <span style="color: var(--text-muted)">Empty</span>
            `;
        }
    }

    // Deterministic Hashing function to get stable score from strings
    function calculateDeterministicScore(a, t, c, o) {
        const combinedString = a + t + c + o;
        let hash = 0;
        for (let i = 0; i < combinedString.length; i++) {
            hash = (hash << 5) - hash + combinedString.charCodeAt(i);
            hash |= 0; // Convert to 32bit integer
        }
        // Normalize hash into a 0-100 score scale representing synergy variance
        return Math.abs(hash % 41); 
    }

    // Generate output display
