        const { audience, task, constraint, output } = currentSelections;
        const scoreDisplay = document.getElementById('score-display');
        const scoreFeedback = document.getElementById('score-feedback');
        const recipeText = document.getElementById('recipe-text');

        // Check if all ingredients exist
        const missingCount = [audience, task, constraint, output].filter(x => !x).length;

        if (missingCount > 0) {
            scoreDisplay.innerText = '--';
            scoreFeedback.innerText = `Missing ${missingCount} core ingredient${missingCount > 1 ? 's' : ''} to calculate recipe penalty.`;
            recipeText.innerText = "Fill all slots to compile your markdown configuration template.";
            return;
        }

        // Calculate missing-ingredient dynamic penalty variance deterministically
        const penaltyScore = calculateDeterministicScore(audience, task, constraint, output);
        scoreDisplay.innerText = penaltyScore + "%";

        let analysisFeedback = "Flawless composition. All operational structural points match structural integrity criteria.";
        if (penaltyScore > 30) analysisFeedback = "High operational friction detected. Constraints conflict structurally with the targeted output formatting.";
        else if (penaltyScore > 15) analysisFeedback = "Moderate execution variance. Fine-tuning formatting parameters recommended.";

        scoreFeedback.innerText = analysisFeedback;

        // Build cleanly structured final markdown template block
        const finalizedPrompt = `# PROMPT CONTEXT RECIPE\n` +
            `## Target Persona/Audience Profile\n` +
            `- Execute processing sequence tailored specifically for: ${audience}\n\n` +
            `## Core Operational Objective\n` +
            `- Task Parameter: ${task}\n\n` +
            `## System Constraints & Guardrails\n` +
            `- Execution Rule: ${constraint}\n\n` +
            `## Structural Output Schema\n` +
            `- Deliver full payload using exactly: ${output}`;

        recipeText.innerText = finalizedPrompt;
    }

    // Action Panel Functions
    function copyRecipe() {
        const text = document.getElementById('recipe-text').innerText;
        navigator.clipboard.writeText(text);
    }

    function downloadRecipe() {
        const text = document.getElementById('recipe-text').innerText;
        const blob = new Blob([text], { type: 'text/markdown' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = 'prompt_recipe_card.md';
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(url);
    }

    // Start App
    initPools();
</script>
</body>
</html>

